def group_anagrams(arr):
    used = [False] * len(arr)
    groups = []
    for i in range(len(arr)):
        if used[i]:
            continue
        group = [arr[i]]
        used[i] = True
        for j in range(i + 1, len(arr)):
            if not used[j] and sorted(arr[i]) == sorted(arr[j]):
                group.append(arr[j])
                used[j] = True
        groups.append(sorted(group))
    groups.sort(key=lambda g: g[0])
    return groups

