def group_anagrams(arr):
    buckets = {}
    for s in arr:
        key = ''.join(sorted(s))
        buckets.setdefault(key, []).append(s)
    groups = [sorted(v) for v in buckets.values()]
    groups.sort(key=lambda g: g[0])
    return groups
